const W = 720;
const unit = 10;

// on worms
let worms = [];
const numWorms = 60;

let wormGraphic;
let traceGraphic;

// on the square
const sqLen = W * 0.8;
const sqx = W / 2 - sqLen / 2;
const sqy = W / 2 - sqLen / 2;

// Color picking
const colsURL = 'https://coolors.co/ffbe0b-fb5607-ff006e-8338ec-3a86ff';
const colors = createCols(colsURL);
const bgColor = 220;

// Take some Colors from coolors URL
function createCols(url) {
  let slaIndex = url.lastIndexOf('/');
  let colStr = url.slice(slaIndex + 1);
  let colArr = colStr.split('-');
  for (let i = 0; i < colArr.length; i++) colArr[i] = '#' + colArr[i];
  return colArr;
}

function setup() {
  createCanvas(W, W);
  noStroke();

  // Prepare worms
  for (let i = 0; i < numWorms; i++) {
    worms.push({
      x: floor(random(2, W / unit - 2)), // x pos
      y: floor(random(2, W / unit - 2)), // y pos
      dir: (Math.PI / 4) * random([1, 3, 5, 7]), // direction
      c: random(colors), // color
      t: random(0, 1), // time
      s: random(0.02, 0.2), // speed
    });
  }

  // Create graphix
  wormGraphic = createGraphics(W, W);
  wormGraphic.noStroke();
  traceGraphic = createGraphics(W, W);
  traceGraphic.noStroke();

  describe('Many small colorful rectangles resembling caterpillars move around on the screen, and when they pass through the large black rectangle in the center, the areas they pass through are erased.');
}

function draw() {
  // clear background
  background(bgColor);

  // Draw square in the center
  fill(0);
  square(sqx, sqy, sqLen);

  // Draw worms
  wormGraphic.clear();

  worms.forEach((worm) => {
    [traceGraphic, wormGraphic].forEach((p, index) => {
      if (index === 0) {
        // for trace
        p.fill(bgColor);
        p.noStroke();
      } else {
        // for worm display
        p.fill(worm.c);
        p.stroke(worm.c);
      }

      // draw worm body
      p.push();
      {
        p.translate(worm.x * unit, worm.y * unit);
        p.rotate(worm.dir - PI / 4);

        const v = unit * sin(worm.t);

        if (worm.t < PI / 2) {
          p.quad(unit + v, v, v, v + unit, -unit, 0, 0, -unit);
        } else {
          p.quad(unit * 2, unit, unit, 2 * unit, -v, unit - v, unit - v, -v);
        }
      }
      p.pop();

      // calcurate next worm properties.
      worm.t += worm.s;
      if (worm.t > PI) {
        worm.t = 0;

        worm.x += round(sqrt(2) * cos(worm.dir));
        worm.y += round(sqrt(2) * sin(worm.dir));

        if (worm.x < 2 || worm.x + 2 > width / unit) {
          worm.dir = PI - worm.dir;
        }
        if (worm.y < 2 || worm.y + 2 > height / unit) {
          worm.dir = -worm.dir;
        }
      }
    });
  });

  // Draw Graphics on canvas
  image(traceGraphic, sqx, sqy, sqLen, sqLen, sqx, sqy, sqLen, sqLen);
  image(wormGraphic, 0, 0, W, W);
}
